#!/usr/bin/env python3
"""Исходник рецептов (компактный формат) -> content/recipes.json.
Запуск: python3 tools/recipes_src.py   (нужен файл /tmp/old_dishes.json только при первой генерации, см. OLD ниже)
Обычно рецепты правят прямо в content/recipes.json: этот файл нужен лишь для массовой генерации."""
import json, os, sys

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')
R = []

def S(t, steps, also=None):
    return {'type': 'stove', 'timeMin': t, 'steps': steps.split('|'), **({'also': also} if also else {})}
def O(t, temp, steps, also=None):
    return {'type': 'oven', 'timeMin': t, 'tempC': temp, 'steps': steps.split('|'), **({'also': also} if also else {})}
def M(t, temp, fill, steps, delay=False, also=None):
    return {'type': 'multicooker', 'timeMin': t, 'tempC': temp, 'fill': fill, 'delayStart': delay, 'steps': steps.split('|'), **({'also': also} if also else {})}
def B(tool, steps, t=3, also=None):
    return {'type': 'blender', 'tool': tool, 'timeMin': t, 'steps': steps.split('|'), **({'also': also} if also else {})}
def T(t, steps, also=None):
    return {'type': 'toaster', 'timeMin': t, 'steps': steps.split('|'), **({'also': also} if also else {})}
def N(steps):
    return {'type': 'none', 'timeMin': 0, 'steps': steps.split('|')}

def parse_ings(s):
    out = []
    for part in s.split(';'):
        part = part.strip()
        if not part: continue
        name, _, g = part.rpartition(' ')
        out.append([name.strip(), float(g) if '.' in g else int(g)])
    return out

def r(id, name, meal, cost, act, tot, ings, methods, tip='', keep='', tags=''):
    R.append({'id': id, 'name': name, 'meal': meal, 'cost': cost, 'servings': 4, 'activeMin': act, 'totalMin': tot,
              'tags': [t for t in tags.split() if t], 'ingredients': parse_ings(ings), 'methods': methods, 'tips': tip, 'keep': keep})

OLD = {}
def old(id, act, tot, methods, keep='', tags='', tip=None):
    d = OLD[id]
    R.append({'id': id, 'name': d['n'], 'meal': d['m'], 'cost': d['c'], 'servings': 4, 'activeMin': act, 'totalMin': tot,
              'tags': [t for t in tags.split() if t], 'ingredients': d['ing'], 'methods': methods, 'tips': tip if tip is not None else d.get('tip', ''), 'keep': keep})

p = '/tmp/old_dishes.json'
if os.path.exists(p):
    for d in json.load(open(p, encoding='utf8')): OLD[d['id']] = d
else:
    print('нет /tmp/old_dishes.json: старые блюда пропущены'); 

# ---------- ЗАВТРАКИ (старые) ----------
if OLD:
    old('b1', 5, 15, [S(10, 'Вскипятите молоко в кастрюле|Всыпьте хлопья и варите 7–10 минут, помешивая|Добавьте нарезанный банан, накройте крышкой на 2 минуты'), M(15, 100, 'не больше половины чаши', 'Выложите хлопья, залейте молоком|Закройте крышку и варите до сигнала|Перед подачей добавьте нарезанный банан', True)], '1 день в холодильнике', 'quick dairy')
