    old('b4', 10, 30, [M(30, 100, 'не больше половины чаши', 'Промойте гречку, выложите в чашу, залейте водой 1:2|Варите до сигнала|Яйца отварите отдельно 8–10 минут на плите', True, ['stove']), S(25, 'Промытую гречку залейте водой 1:2, доведите до кипения|Убавьте огонь, варите под крышкой 15 минут|Отварите яйца вкрутую 8–10 минут, подавайте вместе, добавьте масло')], '', 'egg')
    old('b5', 15, 40, [O(25, 180, 'Смешайте творог, яйцо и овсяную муку|Сформируйте сырники, выложите на пергамент|Запекайте 20–25 минут, подавайте со сметаной'), M(40, 150, 'форма по размеру чаши', 'Смажьте чашу маслом, выложите сырники|Выпекайте 20 минут, переверните|Выпекайте ещё 15–20 минут')], 'в холодильнике 2 дня', 'dairy')
    old('b6', 10, 20, [S(15, 'Измельчите хлопья блендером, смешайте с яйцом и молоком|Жарьте тонкие блинчики на сухой сковороде по 2 минуты с каждой стороны|Начините творогом и бананом, сверните', ['blender'])], '', 'dairy egg quick')
    old('b7', 5, 5, [N('Хлопья залейте йогуртом на 10 минут (или на ночь)|Добавьте нарезанное яблоко|Перемешайте и подавайте')], '', 'quick dairy')
    old('b8', 10, 20, [T(5, 'Яйца сварите вкрутую 9 минут и остудите|Хлеб подсушите в тостере|Выложите ломтики яйца, огурца и сыра', ['stove'])], '', 'egg quick')
    old('b9', 10, 40, [M(40, 100, 'не больше половины чаши', 'Выложите промытое пшено и нарезанную тыкву|Залейте молоком с водой 1:1|Варите до сигнала, добавьте масло', True), S(30, 'Пшено промойте кипятком|Варите с нарезанной тыквой в молоке и воде 25–30 минут|Добавьте масло, дайте постоять 5 минут')], '', 'dairy')
    old('b10', 5, 5, [B('immersion', 'Грушу взбейте погружным блендером с кефиром|Добавьте отруби, дайте постоять 5 минут|Подайте с хлебцами', 2)], '', 'quick dairy')
